    m = int(input_data)

    def count_ways(n):
        total = 0
        for a1 in range(1, n + 1):
            a2 = a1 * 2
            if a2 > n:
                break
            a3 = a2 * 2
            if a3 > n:
                continue
            a4 = a3 * 2
            if a4 > n:
                continue
            total += 1
        return total

    def count_ways_k(n):
        # Enumerate all valid k > 1
        total = 0
        # a1 * k * k * k <= n  => a1 * k^3 <= n
        # k starts from 2
        k = 2
        while True:
            k3 = k * k * k
            if k3 > n:
                break
            max_a1 = n // k3
            if max_a1 < 1:
                break
            total += max_a1
            k += 1
        return total

    if m == 1:
        # Special case: only k=2, a1=1 works if n >= 8, but we need smallest n such that count == 1.
        # For n in [0..7], count=0. For n=8, count=1 (1,2,4,8).
